static int create_parent_directories(const char *path) {
    char *path_copy = strdup(path);
    if (!path_copy)
        return -ENOMEM;

    char *sep;
    while ((sep = strchr(path_copy, '/'))) {
        if (sep == path_copy) {
            path_copy++;
            continue;
        }

        *sep = '\0';
        if (mkdir(path_copy, 0755) == -1) {
            if (errno != EEXIST) {
                free(path_copy);
                return -errno;
            }
        }
        *sep = '/';
    }

    free(path_copy);
    return 0;
}

