static int create_parent_directories(const char *path) {
    char *path_copy = strdup(path);
    if (!path_copy)
        return -ENOMEM;

    char *p = path_copy;
    while ((p = strchr(p, '/'))) {
        if (p == path_copy) {
            p++;
            continue;
        }
        char dir[PATH_MAX];
        strncpy(dir, path_copy, p - path_copy);
        dir[p - path_copy] = '\0';
        if (strcmp(dir, "") == 0 || strcmp(dir, ".") == 0)
            continue;
        if (access(dir, F_OK) != 0) {
            if (mkdir(dir, 0755) != 0) {
                free(path_copy);
                return -errno;
            }
        }
        p++;
    }

    free(path_copy);
    return 0;
}

int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    if (!path || path[0] == '\0')
        return -EINVAL;

    if (parents) {
        int r = create_parent_directories(path);
        if (r < 0)
            return r;
    }

    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, (mode_t) 0644);
    if (fd < 0)
        return -errno;

    mode_t final_mode = mode;
    if (final_mode == 0 || (final_mode & S_IFMT) != 0) {
        final_mode = (mode_t) 0644;
    }

    if (fchmod(fd, final_mode) < 0) {
        close(fd);
        return -errno;
    }

    if (chown(path, uid, gid) < 0) {
        close(fd);
        return -errno;
    }

    struct timespec times[2];
    times[0].tv_nsec = USEC_TO_NSEC(stamp);
    times[1].tv_nsec = USEC_TO_NSEC(stamp);

    if (utimensat(AT_FDCWD, path, times, 0) < 0) {
        close(fd);
        return -errno;
    }

    close(fd);
    return 0;
}

